25	export const ImageCropDialog = ({
26	  imageData,
27	  isOpen,
28	  onConfirm,
29	  onCancel,
30	}: Props) => {
31	  const { t } = useTranslation(undefined, {
32	    keyPrefix: "dialog.image-crop",
33	  });
34	  const imgRef = useRef<HTMLImageElement | null>(null);
35	  const [crop, setCrop] = useState<Crop>();
36	  const [completedCrop, setCompletedCrop] = useState<PixelCrop>();
37	  const [isLoading, setIsLoading] = useState(false);
38	
39	  useEffect(() => {
40	    if (isOpen) {
41	      setCrop(undefined);
42	      setCompletedCrop(undefined);
43	    }
44	  }, [isOpen]);
45	
46	  const handleConfirm = () => {
47	    if (!imgRef.current || !completedCrop) return;
48	    if (completedCrop.width === 0 || completedCrop.height === 0) return;
49	
50	    try {
51	      setIsLoading(true);
52	      const croppedImage = getCroppedImg(imgRef.current, completedCrop, 300);
53	      onConfirm(croppedImage);
54	    } catch (e) {
55	      console.error(e);
56	      toast.error(t("crop-error"));
57	    } finally {
58	      setIsLoading(false);
59	    }
60	  };
61	
62	  if (!imageData) return null;
63	
64	  return (
65	    <Dialog open={isOpen} onOpenChange={(open) => !open && onCancel()}>
66	      <DialogContent>
67	        <DialogHeader>
68	          <DialogTitle>{t("title")}</DialogTitle>
69	          <DialogDescription>{t("description")}</DialogDescription>
70	        </DialogHeader>
71	        <div className="flex justify-center max-h-[60vh] overflow-auto">
72	          <ReactCrop
73	            crop={crop}
74	            onChange={(c) => setCrop(c)}
75	            onComplete={(c) => setCompletedCrop(c)}
76	            circularCrop
77	            aspect={1}
78	            keepSelection
79	          >
80	            <img
81	              ref={imgRef}
82	              src={imageData}
83	              alt="Crop"
84	              className="max-w-full"
85	            />
86	          </ReactCrop>
87	        </div>
88	        <DialogFooter>
89	          <DialogClose asChild>
90	            <Button variant="outline" size="sm" onClick={onCancel}>
91	              {t("cancel")}
92	            </Button>
93	          </DialogClose>
94	          <Button
95	            variant="default"
96	            size="sm"
97	            onClick={handleConfirm}
98	            disabled={!crop || isLoading}
99	          >
100	            {isLoading && <Spinner />}
101	            {t("crop")}
102	          </Button>
103	        </DialogFooter>
104	      </DialogContent>
105	    </Dialog>
106	  );
107	};
