87	export const EditMode = ({
88	  member,
89	  isNew = false,
90	  onSaved,
91	  onDirtyChange,
92	  onSaveStatusChange,
93	  onAutosaveFlush,
94	  activeTab,
95	  onTabChange,
96	}: Props) => {
97	  const { t } = useTranslation(undefined, {
98	    keyPrefix: "sheet.edit-mode",
99	  });
100	  const { updateMemberPartial, members } = useMemberStore();
101	  const restrictions = useTreeStore((s) => s.selectedTree?.restrictions ?? []);
102	  const currentTreeId = useTreeStore((s) => s.selectedTree?.id);
103	  const treeLinksEnabled = useFeature("tree_links");
104	  const eventsEnabled =
105	    useFeature("events") && !restrictions.includes("events");
106	  const storiesEnabled =
107	    useFeature("stories") && !restrictions.includes("stories");
108	  const documentsEnabled =
109	    useFeature("sources") && !restrictions.includes("sources");
110	  const galleryEnabled =
111	    useFeature("gallery") && !restrictions.includes("gallery");
112	  const tasksEnabled =
113	    useFeature("research_tasks") && !restrictions.includes("tasks");
114	  const diseasesEnabled = !restrictions.includes("diseases");
115	  const mapEnabled = !restrictions.includes("map");
116	  const biographyEnabled = !restrictions.includes("biography");
117	
118	  const [formData, setFormData] = useState<Member>(member);
119	  const [initialData, setInitialData] = useState<Member>(member);
120	  const [selectedImage, setSelectedImage] = useState<string | null>(null);
121	  const [errors, setErrors] = useState<{
122	    firstName?: string;
123	    lastName?: string;
124	  }>({});
125	  const [recordsMounted, setRecordsMounted] = useState(activeTab === "records");
126	  const [isDirty, setIsDirty] = useState(false);
127	  const [saveStatus, setSaveStatus] = useState<SaveStatus>("idle");
128	  // These identifiers are deliberately captured for the editor's lifetime.
129	  // A delayed save must never resolve the currently active tree after a switch.
130	  const editorTreeIdRef = useRef(currentTreeId);
131	  const editorMemberIdRef = useRef(member.id);
132	  const formDataRef = useRef(formData);
133	  const isDirtyRef = useRef(isDirty);
134	  const saveChainRef = useRef<Promise<void>>(Promise.resolve());
135	  const latestSaveRevisionRef = useRef(0);
136	  const fileInputRef = useRef<HTMLInputElement>(null);
137	  const firstNameRef = useRef<HTMLInputElement>(null);
138	  const lastNameRef = useRef<HTMLInputElement>(null);
139	  const lastDuplicateSignatureRef = useRef<string | null>(null);
140	
141	  formDataRef.current = formData;
142	  isDirtyRef.current = isDirty;
143	
144	  useEffect(() => {
145	    setFormData(member);
146	    setInitialData(member);
147	    setErrors({});
148	    setIsDirty(false);
149	    onDirtyChange?.(false);
150	    // Autosave (for existing members) persists in place and updates the
151	    // `member` prop identity without the user switching members — only reset
152	    // the form when a genuinely different member is opened.
153	    // eslint-disable-next-line react-hooks/exhaustive-deps
154	  }, [member.id]);
155	
156	  useEffect(() => {
157	    onSaveStatusChange?.(saveStatus);
158	  }, [saveStatus, onSaveStatusChange]);
159	
160	  // Records content is lazy-mounted the first time its tab becomes active.
161	  // Deriving this from `activeTab` (rather than only the tab-click handler)
162	  // covers restores that land directly on Records — e.g. a page refresh, where
163	  // the persisted tab is selected but no click fires to trigger the mount.
164	  useEffect(() => {
165	    if (activeTab === "records") setRecordsMounted(true);
166	  }, [activeTab]);
167	
168	  useEffect(() => {
169	    const dirty =
170	      (formData.academicTitle || "") !== (initialData.academicTitle || "") ||
171	      formData.firstName !== initialData.firstName ||
172	      (formData.middleNames || "") !== (initialData.middleNames || "") ||
173	      (formData.baptismalName || "") !== (initialData.baptismalName || "") ||
174	      formData.lastName !== initialData.lastName ||
175	      (formData.maidenName || "") !== (initialData.maidenName || "") ||
176	      formData.gender !== initialData.gender ||
177	      (formData.imageData || "") !== (initialData.imageData || "") ||
178	      formData.date.birth !== initialData.date.birth ||
179	      (formData.date.death || "") !== (initialData.date.death || "") ||
180	      formData.deceased !== initialData.deceased ||
181	      formData.adopted !== initialData.adopted ||
182	      (formData.additionalData || "") !== (initialData.additionalData || "") ||
183	      (formData.birthplace || "") !== (initialData.birthplace || "") ||
184	      (formData.hometown || "") !== (initialData.hometown || "") ||
185	      (formData.cemetery || "") !== (initialData.cemetery || "") ||
186	      JSON.stringify(formData.placesLived) !==
187	        JSON.stringify(initialData.placesLived) ||
188	      formData.parents.paternalParent !== initialData.parents.paternalParent ||
189	      formData.parents.maternalParent !== initialData.parents.maternalParent ||
190	      (formData.linkedTreeId ?? null) !== (initialData.linkedTreeId ?? null);
191	
192	    setIsDirty(dirty);
193	    onDirtyChange?.(dirty);
194	  }, [formData, initialData, onDirtyChange]);
195	
196	  const eligibleParents = useMemo(() => {
197	    const excluded = getDescendants(member.id, members);
198	    excluded.add(member.id);
199	    return members.filter((m) => !excluded.has(m.id));
200	  }, [member.id, members]);
201	
202	  const handleChange = (field: keyof Member, value: unknown) => {
203	    setFormData((prev) => ({ ...prev, [field]: value }));
204	  };
205	
206	  function handleSelectImage() {
207	    fileInputRef.current?.click();
208	  }
209	
210	  function handleFileChange(e: ChangeEvent<HTMLInputElement>) {
211	    const file = e.target.files?.[0];
212	    e.target.value = "";
213	    if (!file) return;
214	
215	    const reader = new FileReader();
216	    reader.onload = (event) => {
217	      setSelectedImage(event.target?.result as string);
218	    };
219	    reader.onerror = () => toast.error(t("toast-error-file"));
220	    reader.readAsDataURL(file);
221	  }
222	
223	  const onConfirm = (imageData: string) => {
224	    handleChange("imageData", imageData);
225	    setSelectedImage(null);
226	  };
227	
228	  const handleDateChange = (
229	    field: "birth" | "death",
230	    dateString: string | null,
231	  ) => {
232	    if (field === "death" && dateString && formData.date.birth) {
233	      if (comparePartialDates(dateString, formData.date.birth) < 0) {
234	        toast.error(t("toast-error-death"));
235	        return;
236	      }
237	    }
238	
239	    if (field === "birth" && dateString && formData.date.death) {
240	      if (comparePartialDates(formData.date.death, dateString) < 0) {
241	        toast.error(t("toast-error-birth"));
242	        return;
243	      }
244	    }
245	
246	    setFormData((prev) => ({
247	      ...prev,
248	      deceased: field === "death" && dateString ? true : prev.deceased,
249	      date: {
250	        ...prev.date,
251	        [field]: dateString,
252	      },
253	    }));
254	  };
255	
256	  const handleGenderChange = (value: Gender) => {
257	    if (!value) return;
258	    handleChange("gender", value);
259	  };
260	
261	  const persistSnapshot = useCallback(
262	    async (
263	      snapshot: Member,
264	      revision: number,
265	      opts?: { autosave?: boolean },
266	    ): Promise<boolean> => {
267	      const isCurrent = () => revision === latestSaveRevisionRef.current;
268	      const nextErrors: { firstName?: string; lastName?: string } = {};
269	      if (!snapshot.firstName.trim())
270	        nextErrors.firstName = t("error-firstname-required");
271	      if (!snapshot.lastName.trim())
272	        nextErrors.lastName = t("error-lastname-required");
273	      if (isCurrent()) setErrors(nextErrors);
274	      if (Object.keys(nextErrors).length > 0) {
275	        if (opts?.autosave && isCurrent()) {
276	          setSaveStatus("idle");
277	        } else if (!opts?.autosave && isCurrent()) {
278	          (nextErrors.firstName ? firstNameRef : lastNameRef).current?.focus();
279	        }
280	        return false;
281	      }
282	
283	      // Same-named people are only treated as duplicates once a birth date has
284	      // been entered; without one we allow namesakes to be created freely.
285	      const duplicate = snapshot.date.birth
286	        ? members.find(
287	            (m) =>
288	              m.id !== member.id &&
289	              m.firstName === snapshot.firstName &&
290	              (m.middleNames || "") === (snapshot.middleNames || "") &&
291	              (m.baptismalName || "") === (snapshot.baptismalName || "") &&
292	              m.lastName === snapshot.lastName &&
293	              m.gender === snapshot.gender &&
294	              m.date.birth === snapshot.date.birth &&
295	              m.date.death === snapshot.date.death,
296	          )
297	        : undefined;
298	
299	      if (duplicate) {
300	        const signature = [
301	          snapshot.firstName,
302	          snapshot.middleNames || "",
303	          snapshot.baptismalName || "",
304	          snapshot.lastName,
305	          snapshot.gender,
306	          snapshot.date.birth,
307	          snapshot.date.death || "",
308	        ].join("|");
309	        if (isCurrent() && lastDuplicateSignatureRef.current !== signature) {
310	          toast.error(t("toast-error-duplicate"));
311	          lastDuplicateSignatureRef.current = signature;
312	        }
313	        if (isCurrent()) setSaveStatus("error");
314	        return false;
315	      }
316	      if (isCurrent()) lastDuplicateSignatureRef.current = null;
317	
318	      if (isNew) {
319	        onSaved?.(snapshot);
320	        return true;
321	      }
322	
323	      setSaveStatus("saving");
324	      try {
325	        const treeId = editorTreeIdRef.current;
326	        if (!treeId) return false;
327	        const result = await updateMemberPartial(
328	          editorMemberIdRef.current,
329	          {
330	            academicTitle: snapshot.academicTitle || null,
331	            firstName: snapshot.firstName,
332	            middleNames: snapshot.middleNames || null,
333	            baptismalName: snapshot.baptismalName || null,
334	            lastName: snapshot.lastName,
335	            maidenName: snapshot.maidenName || null,
336	            gender: snapshot.gender,
337	            imageData: snapshot.imageData || undefined,
338	            dateOfBirth: snapshot.date.birth,
339	            dateOfDeath: snapshot.date.death || null,
340	            deceased: snapshot.deceased,
341	            adopted: snapshot.adopted,
342	            additionalData: snapshot.additionalData || null,
343	            birthplace: snapshot.birthplace || null,
344	            hometown: snapshot.hometown || null,
345	            cemetery: snapshot.cemetery || null,
346	            placesLived:
347	              snapshot.placesLived.length > 0
348	                ? JSON.stringify(snapshot.placesLived)
349	                : null,
350	            paternalParentId: snapshot.parents.paternalParent,
351	            maternalParentId: snapshot.parents.maternalParent,
352	            ...(snapshot.linkedTreeId !== undefined
353	              ? { linkedTreeId: snapshot.linkedTreeId }
354	              : {}),
355	          },
356	          treeId,
357	        );
358	        if (!opts?.autosave && isCurrent()) {
359	          toast.success(t("toast-success"));
360	        }
361	        // Bridge person whose counterpart tree the editor may not write: the
362	        // save worked but the linked copy drifted — say so.
363	        if (isCurrent() && result?.bridgeSync === "skipped_no_access") {
364	          toast.info(t("toast-bridge-sync-skipped"));
365	        }
366	        // Settle the dirty baseline on the snapshot that was actually
367	        // persisted — if the user kept typing during the in-flight save,
368	        // formData has since moved on and stays (correctly) dirty.
369	        // Serialization prevents reordered writes; this guard also prevents an
370	        // older response from replacing the status of a newer queued revision.
371	        if (isCurrent()) {
372	          setInitialData(snapshot);
373	          setSaveStatus("saved");
374	        }
375	        if (!opts?.autosave && isCurrent()) {
376	          onSaved?.(snapshot);
377	        }
378	        return true;
379	      } catch (err: unknown) {
380	        if (!isCurrent()) return false;
381	        if (err instanceof ApiError && err.status === 413) {
382	          const bucket = getQuotaBucket(err.message);
383	          if (bucket) {
