400	  // Saves are serialized through one chain.  The debounce below coalesces
401	  // rapid form changes into one queued snapshot, and every response carries a
402	  // revision so a late result cannot overwrite newer editor state.
403	  const save = useCallback(
404	    (opts?: { autosave?: boolean }): Promise<boolean> => {
405	      const snapshot = formDataRef.current;
406	      const revision = ++latestSaveRevisionRef.current;
407	      const task = saveChainRef.current.then(() =>
408	        persistSnapshot(snapshot, revision, opts),
409	      );
410	      saveChainRef.current = task.then(
411	        () => undefined,
412	        () => undefined,
413	      );
414	      return task;
415	    },
416	    [persistSnapshot],
417	  );
