424	  // Keep a stable debounced trigger that always calls the freshest `save`
425	  // (via a ref) so the debounce doesn't need to be recreated on every
426	  // keystroke, which would otherwise reset its timer.
427	  const saveRef = useRef(save);
428	  saveRef.current = save;
429	  const autosave = useMemo(
430	    () =>
431	      debounce(() => {
