3	/** Convert a base64 data URL (such as a canvas crop) into an uploadable file. */
4	export function dataUrlToFile(dataUrl: string, filename: string): File {
5	  const match = /^data:([^;,]+);base64,(.+)$/.exec(dataUrl);
6	  if (!match) throw new Error("Invalid image data URL");
7	
8	  const [, type, encoded] = match;
9	  const binary = atob(encoded);
10	  const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
11	  return new File([bytes], filename, { type });
12	}
13	
14	export function getCroppedImg(
15	  image: HTMLImageElement,
16	  crop: PixelCrop,
17	  outputWidth?: number,
18	): string {
19	  const canvas = document.createElement("canvas");
20	
21	  const scaleX = image.naturalWidth / image.width;
22	  const scaleY = image.naturalHeight / image.height;
23	
24	  const targetWidth = outputWidth || crop.width;
25	  const targetHeight = outputWidth
26	    ? (crop.height / crop.width) * outputWidth
27	    : crop.height;
28	
29	  canvas.width = targetWidth;
30	  canvas.height = targetHeight;
31	
32	  const ctx = canvas.getContext("2d");
33	  if (!ctx) {
34	    throw new Error("No 2d context");
35	  }
36	
37	  ctx.imageSmoothingQuality = "high";
38	  ctx.drawImage(
39	    image,
40	    crop.x * scaleX,
41	    crop.y * scaleY,
42	    crop.width * scaleX,
43	    crop.height * scaleY,
44	    0,
45	    0,
46	    targetWidth,
47	    targetHeight,
48	  );
49	
50	  return canvas.toDataURL("image/jpeg");
51	}
