1	import { useEffect, useState } from "react";
2	import { getAuthToken, getPublicTreeToken } from "@/services/api";
3	
4	const PROTECTED_MEDIA_PREFIXES = [
5	  "/api/media/",
6	  "/api/auth/profile/image/",
7	  "/api/friends/",
8	];
9	
10	function isProtectedMediaUrl(src: string): boolean {
11	  return PROTECTED_MEDIA_PREFIXES.some((prefix) => src.startsWith(prefix));
12	}
13	
14	// Module-level cache: media URL -> blob URL. Avoids re-fetching the same file
15	// during a session. Blob URLs are document-scoped so this is effectively
16	// application-lifetime — fine because a logout clears store data anyway.
17	const _cache = new Map<string, string>();
18	
19	/**
20	 * Resolves a media URL to one the browser can load without an Authorization
21	 * header. Non-media URLs (data: URLs, nullish values) are returned unchanged.
22	 * Media URLs are fetched once with the Bearer or public-tree unlock token and
23	 * replaced with a blob URL.
24	 */
25	export function useMediaUrl(
26	  src: string | null | undefined,
27	): string | null | undefined {
28	  const [resolved, setResolved] = useState<string | null | undefined>(() => {
29	    if (!src || !isProtectedMediaUrl(src)) return src;
30	    return _cache.get(src) ?? undefined;
31	  });
32	
33	  useEffect(() => {
34	    if (!src || !isProtectedMediaUrl(src)) {
35	      setResolved(src);
36	      return;
37	    }
38	    if (_cache.has(src)) {
39	      setResolved(_cache.get(src));
40	      return;
41	    }
42	
43	    let cancelled = false;
44	    const headers = mediaHeaders();
45	    fetch(src, {
46	      headers,
47	    })
48	      .then((r) => {
49	        if (!r.ok) throw new Error(String(r.status));
50	        return r.blob();
51	      })
52	      .then((blob) => {
53	        if (cancelled) return;
54	        const objectUrl = URL.createObjectURL(blob);
55	        _cache.set(src, objectUrl);
56	        setResolved(objectUrl);
57	      })
58	      .catch(() => {
59	        if (!cancelled) setResolved(null);
60	      });
61	
62	    return () => {
63	      cancelled = true;
64	    };
65	  }, [src]);
66	
67	  return resolved;
68	}
69	
70	/** Fetch a media URL with the Bearer token and return a fresh object URL.
71	 *  Caller owns the returned URL and is responsible for revoking it. */
72	async function fetchMediaObjectUrl(src: string): Promise<string> {
73	  const r = await fetch(src, {
74	    headers: mediaHeaders(),
75	  });
76	  if (!r.ok) throw new Error(String(r.status));
77	  return URL.createObjectURL(await r.blob());
78	}
79	
80	function mediaHeaders(): Record<string, string> {
81	  const headers: Record<string, string> = {};
82	  const token = getAuthToken();
83	  const publicToken = getPublicTreeToken();
84	  if (token) headers.Authorization = `Bearer ${token}`;
85	  if (publicToken) headers["X-Public-Tree-Token"] = publicToken;
86	  return headers;
87	}
88	
89	/**
90	 * Download a media file, fetching it with the auth token first so the request
91	 * carries the Authorization header an <a download> link cannot. Non-media
92	 * sources (data:/blob: URLs) are downloaded directly.
93	 */
94	export async function downloadMedia(
95	  src: string,
96	  filename: string,
97	): Promise<void> {
98	  const isMedia = isProtectedMediaUrl(src);
99	  const url = isMedia ? await fetchMediaObjectUrl(`${src}?download=true`) : src;
100	  const a = document.createElement("a");
101	  a.href = url;
102	  a.download = filename;
103	  document.body.appendChild(a);
104	  a.click();
105	  a.remove();
106	  if (isMedia) URL.revokeObjectURL(url);
107	}
108	
109	/**
110	 * Open a media file in a new tab, fetching it with the auth token first.
111	 * Non-media sources (data:/blob: URLs) are opened directly.
112	 */
113	export async function openMedia(src: string): Promise<void> {
114	  const url = isProtectedMediaUrl(src) ? await fetchMediaObjectUrl(src) : src;
115	  window.open(url, "_blank", "noopener");
116	}
